CREATE OR REPLACE FUNCTION app_security.impl_fulfill_data_export(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_export jsonb;
  v_target_user_id uuid;
  v_private_details jsonb;
BEGIN
  -- Authentication and owner / administrator-AAL2 authorization happen inside the base
  -- function and raise on failure; nothing below runs for an unauthorized caller.
  v_export := app_security.impl_fulfill_data_export_base(p_request_id);

  SELECT user_id INTO v_target_user_id
  FROM public.privacy_requests
  WHERE id = p_request_id AND request_type = 'export_data';

  SELECT to_jsonb(pd) INTO v_private_details
  FROM (
    SELECT d.full_name, d.pin_code, l.name AS locality, c.name AS district, d.state,
           d.preferred_language, d.onboarding_completed_at, d.created_at, d.updated_at
    FROM public.user_private_details d
    LEFT JOIN public.localities l ON l.id = d.locality_id
    LEFT JOIN public.cities c ON c.id = d.city_id
    WHERE d.user_id = v_target_user_id
  ) pd;

  RETURN v_export || pg_catalog.jsonb_build_object('private_details', v_private_details);
END;
$function$

CREATE OR REPLACE FUNCTION app_security.impl_seller_transition_listing(p_listing_id uuid, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_caller_id uuid;
  v_listing record;
  v_new_status public.listing_status_enum;
  v_renewal_limit constant integer := 3;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  IF app_security.get_account_status(v_caller_id) != 'active' THEN
    RAISE EXCEPTION 'account is not active';
  END IF;

  IF NOT app_security.has_current_policy_acceptance(v_caller_id) THEN
    RAISE EXCEPTION 'POLICY_ACCEPTANCE_REQUIRED: Re-acceptance of Public Beta policies is required';
  END IF;

  SELECT * INTO v_listing
  FROM public.listings
  WHERE id = p_listing_id
  FOR UPDATE;

  IF v_listing.id IS NULL THEN
    RAISE EXCEPTION 'listing not found';
  END IF;

  IF v_listing.seller_id != v_caller_id THEN
    RAISE EXCEPTION 'caller does not own this listing';
  END IF;

  CASE p_action
    WHEN 'pause' THEN
      IF v_listing.status != 'active' THEN
        RAISE EXCEPTION 'only active listings can be paused (current: %)', v_listing.status;
      END IF;
      v_new_status := 'paused'::public.listing_status_enum;

      UPDATE public.listings
      SET status = v_new_status,
          updated_at = pg_catalog.clock_timestamp()
      WHERE id = p_listing_id;

      PERFORM app_security.log_audit_event(
        'listing.paused',
        'listings',
        p_listing_id,
        jsonb_build_object('revision', v_listing.revision)
      );

    WHEN 'resume' THEN
      IF v_listing.status != 'paused' THEN
        RAISE EXCEPTION 'only paused listings can be resumed (current: %)', v_listing.status;
      END IF;
      IF v_listing.published_at IS NULL THEN
        RAISE EXCEPTION 'unapproved listing cannot be resumed';
      END IF;
      IF v_listing.expires_at IS NOT NULL AND v_listing.expires_at <= pg_catalog.clock_timestamp() THEN
        RAISE EXCEPTION 'expired listing cannot be resumed directly';
      END IF;
      v_new_status := 'active'::public.listing_status_enum;

      UPDATE public.listings
      SET status = v_new_status,
          updated_at = pg_catalog.clock_timestamp()
      WHERE id = p_listing_id;

      PERFORM app_security.log_audit_event(
        'listing.resumed',
        'listings',
        p_listing_id,
        jsonb_build_object('revision', v_listing.revision)
      );

    WHEN 'reserve' THEN
      IF v_listing.status != 'active' THEN
        RAISE EXCEPTION 'only active listings can be reserved (current: %)', v_listing.status;
      END IF;
      v_new_status := 'reserved'::public.listing_status_enum;

      UPDATE public.listings
      SET status = v_new_status,
          updated_at = pg_catalog.clock_timestamp()
      WHERE id = p_listing_id;

      PERFORM app_security.log_audit_event(
        'listing.reserved',
        'listings',
        p_listing_id,
        jsonb_build_object('revision', v_listing.revision)
      );

    WHEN 'unreserve' THEN
      IF v_listing.status != 'reserved' THEN
        RAISE EXCEPTION 'only reserved listings can be unreserved (current: %)', v_listing.status;
      END IF;
      v_new_status := 'active'::public.listing_status_enum;

      UPDATE public.listings
      SET status = v_new_status,
          updated_at = pg_catalog.clock_timestamp()
      WHERE id = p_listing_id;

      PERFORM app_security.log_audit_event(
        'listing.unreserved',
        'listings',
        p_listing_id,
        jsonb_build_object('revision', v_listing.revision)
      );

    WHEN 'mark_sold' THEN
      IF v_listing.status NOT IN ('active', 'reserved', 'paused') THEN
        RAISE EXCEPTION 'listing in status % cannot be marked sold', v_listing.status;
      END IF;
      v_new_status := 'sold'::public.listing_status_enum;

      UPDATE public.listings
      SET status = v_new_status,
          sold_at = pg_catalog.clock_timestamp(),
          updated_at = pg_catalog.clock_timestamp()
      WHERE id = p_listing_id;

      PERFORM app_security.log_audit_event(
        'listing.sold',
        'listings',
        p_listing_id,
        jsonb_build_object('revision', v_listing.revision)
      );

    WHEN 'renew' THEN
      IF v_listing.status != 'expired' THEN
        RAISE EXCEPTION 'only expired listings can be renewed (current: %)', v_listing.status;
      END IF;
      IF v_listing.renewal_count >= v_renewal_limit THEN
        RAISE EXCEPTION 'renewal limit of % reached', v_renewal_limit;
      END IF;
      v_new_status := 'pending_review'::public.listing_status_enum;

      UPDATE public.listings
      SET status = v_new_status,
          renewal_count = v_listing.renewal_count + 1,
          submitted_at = pg_catalog.clock_timestamp(),
          updated_at = pg_catalog.clock_timestamp()
      WHERE id = p_listing_id;

      PERFORM app_security.log_audit_event(
        'listing.renewed',
        'listings',
        p_listing_id,
        jsonb_build_object('revision', v_listing.revision, 'renewal_count', v_listing.renewal_count + 1)
      );

    ELSE
      RAISE EXCEPTION 'invalid transition action: %', p_action;
  END CASE;

  RETURN jsonb_build_object('success', true, 'new_status', v_new_status);
END;
$function$

CREATE OR REPLACE FUNCTION app_security.is_active_staff_aal2(p_required_role staff_role_enum)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_user_id uuid;
  v_user_role public.staff_role_enum;
  v_status public.account_status_enum;
  v_aal text;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN false;
  END IF;

  -- 1. Check account status is active
  SELECT account_status INTO v_status
  FROM public.user_accounts
  WHERE user_id = v_user_id;

  IF v_status IS DISTINCT FROM 'active' THEN
    RETURN false;
  END IF;

  -- 2. Check JWT assurance level claim is aal2
  v_aal := (auth.jwt() ->> 'aal');
  IF v_aal IS DISTINCT FROM 'aal2' THEN
    RETURN false;
  END IF;

  -- 3. Check staff role assignment
  SELECT role INTO v_user_role
  FROM public.staff_roles
  WHERE user_id = v_user_id;

  IF v_user_role IS NULL THEN
    RETURN false;
  END IF;

  -- Administrators satisfy all role requirements
  IF v_user_role = 'administrator' THEN
    RETURN true;
  END IF;

  RETURN v_user_role = p_required_role;
END;
$function$
